#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include "cJSON.h"
#include "lodepng.h"

using namespace std;

typedef vector<vector<float>> Matrix;
typedef vector<float> Vector;

// Load weights from JSON file
void loadWeights(const string& filename,
                 Matrix& input_weight, Vector& input_bias,
                 Matrix& hidden_weight, Vector& hidden_bias,
                 Matrix& output_weight, Vector& output_bias) {
    ifstream file(filename);
    string content((istreambuf_iterator<char>(file)), istreambuf_iterator<char>());

    cJSON *json = cJSON_Parse(content.c_str());
    if (!json) {
        cerr << "Failed to parse JSON" << endl;
        exit(1);
    }

    // Load input layer weights (784x16)
    cJSON *input_w = cJSON_GetObjectItem(json, "input_layer.weight");
    if (input_w) {
        input_weight.clear();
        cJSON *row = input_w->child;
        while (row) {
            Vector v;
            cJSON *val = row->child;
            while (val) {
                v.push_back(val->valuedouble);
                val = val->next;
            }
            input_weight.push_back(v);
            row = row->next;
        }
    }

    // Load input layer bias (16)
    cJSON *input_b = cJSON_GetObjectItem(json, "input_layer.bias");
    if (input_b) {
        input_bias.clear();
        cJSON *val = input_b->child;
        while (val) {
            input_bias.push_back(val->valuedouble);
            val = val->next;
        }
    }

    // Load hidden layer weights (16x16)
    cJSON *hidden_w = cJSON_GetObjectItem(json, "hidden_layer.weight");
    if (hidden_w) {
        hidden_weight.clear();
        cJSON *row = hidden_w->child;
        while (row) {
            Vector v;
            cJSON *val = row->child;
            while (val) {
                v.push_back(val->valuedouble);
                val = val->next;
            }
            hidden_weight.push_back(v);
            row = row->next;
        }
    }

    // Load hidden layer bias (16)
    cJSON *hidden_b = cJSON_GetObjectItem(json, "hidden_layer.bias");
    if (hidden_b) {
        hidden_bias.clear();
        cJSON *val = hidden_b->child;
        while (val) {
            hidden_bias.push_back(val->valuedouble);
            val = val->next;
        }
    }

    // Load output layer weights (10x16)
    cJSON *output_w = cJSON_GetObjectItem(json, "output_layer.weight");
    if (output_w) {
        output_weight.clear();
        cJSON *row = output_w->child;
        while (row) {
            Vector v;
            cJSON *val = row->child;
            while (val) {
                v.push_back(val->valuedouble);
                val = val->next;
            }
            output_weight.push_back(v);
            row = row->next;
        }
    }

    // Load output layer bias (10)
    cJSON *output_b = cJSON_GetObjectItem(json, "output_layer.bias");
    if (output_b) {
        output_bias.clear();
        cJSON *val = output_b->child;
        while (val) {
            output_bias.push_back(val->valuedouble);
            val = val->next;
        }
    }

    cJSON_Delete(json);
}

// Load and preprocess PNG image to 28x28 grayscale
Vector loadImage(const string& filename) {
    vector<unsigned char> image;
    unsigned width, height;

    unsigned error = lodepng::decode(image, width, height, filename);
    if (error) {
        cerr << "Failed to load image: " << lodepng_error_text(error) << endl;
        exit(1);
    }

    // Convert to grayscale 28x28
    Vector result(784, 0.0f);

    for (unsigned y = 0; y < min((unsigned)28, height); y++) {
        for (unsigned x = 0; x < min((unsigned)28, width); x++) {
            // Get pixel value (assuming RGBA or RGB)
            unsigned char r, g, b;
            size_t idx = (y * width + x) * 4;

            if (idx + 2 < image.size()) {
                r = image[idx];
                g = image[idx + 1];
                b = image[idx + 2];
            } else {
                r = g = b = 0;
            }

            // Convert to grayscale (0-1 range)
            float gray = (r + g + b) / (3.0f * 255.0f);
            result[y * 28 + x] = gray;
        }
    }

    return result;
}

// Matrix-vector multiplication
Vector matmul(const Matrix& weights, const Vector& input, const Vector& bias) {
    Vector output(weights.size(), 0.0f);

    for (size_t i = 0; i < weights.size(); i++) {
        float sum = bias[i];
        for (size_t j = 0; j < input.size(); j++) {
            sum += weights[i][j] * input[j];
        }
        output[i] = sum;
    }

    return output;
}

// ReLU activation
Vector relu(const Vector& input) {
    Vector output = input;
    for (auto& val : output) {
        if (val < 0) val = 0;
    }
    return output;
}

// Forward pass through network
int predictDigit(const Vector& image,
                 const Matrix& input_weight, const Vector& input_bias,
                 const Matrix& hidden_weight, const Vector& hidden_bias,
                 const Matrix& output_weight, const Vector& output_bias) {

    // First layer: input -> hidden
    Vector hidden = matmul(input_weight, image, input_bias);
    hidden = relu(hidden);

    // Second layer: hidden -> hidden
    Vector hidden2 = matmul(hidden_weight, hidden, hidden_bias);
    hidden2 = relu(hidden2);

    // Output layer: hidden -> output
    Vector output = matmul(output_weight, hidden2, output_bias);

    // Find argmax
    int prediction = 0;
    float max_val = output[0];
    for (size_t i = 1; i < output.size(); i++) {
        if (output[i] > max_val) {
            max_val = output[i];
            prediction = i;
        }
    }

    return prediction;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        cerr << "Usage: " << argv[0] << " weights.json image.png" << endl;
        return 1;
    }

    string weights_file = argv[1];
    string image_file = argv[2];

    // Load weights
    Matrix input_weight, hidden_weight, output_weight;
    Vector input_bias, hidden_bias, output_bias;
    loadWeights(weights_file, input_weight, input_bias,
                hidden_weight, hidden_bias, output_weight, output_bias);

    // Load image
    Vector image = loadImage(image_file);

    // Predict
    int prediction = predictDigit(image, input_weight, input_bias,
                                  hidden_weight, hidden_bias,
                                  output_weight, output_bias);

    // Output only the digit
    cout << prediction << endl;

    return 0;
}
